    public static void main(String[] args) throws Exception {
        String filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__o428_do/app.log";
        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String line;

        Map<String, Integer> levelCount = new TreeMap<>();
        Map<String, Integer> componentErrors = new TreeMap<>();
        Set<String> uniqueErrorMessages = new TreeSet<>();
        Map<String, Integer> hourCount = new TreeMap<>();

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            // Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
            int closeBracket = line.indexOf(']');
            if (closeBracket == -1) continue;

            String dateTime = line.substring(1, closeBracket); // YYYY-MM-DD HH:MM:SS
            String rest = line.substring(closeBracket + 2); // LEVEL (component) - message

            // Extract level
            int spaceIdx = rest.indexOf(' ');
            if (spaceIdx == -1) continue;
            String level = rest.substring(0, spaceIdx);
            rest = rest.substring(spaceIdx + 1);

            // Extract component in parentheses
            int openParen = rest.indexOf('(');
            int closeParen = rest.indexOf(')');
            if (openParen == -1 || closeParen == -1) continue;
            String component = rest.substring(openParen + 1, closeParen);

            // Extract message after " - "
            int dashIdx = rest.indexOf(" - ", closeParen);
            String message = "";
            if (dashIdx != -1) {
                message = rest.substring(dashIdx + 3);
            }

            // Count levels
            levelCount.merge(level, 1, Integer::sum);

            // Count errors by component
            if (level.equals("ERROR")) {
                componentErrors.merge(component, 1, Integer::sum);
                uniqueErrorMessages.add(message);
            }

            // Count by hour
            String hour = dateTime.substring(11, 13);
            hourCount.merge(hour, 1, Integer::sum);
        }
        br.close();

        StringBuilder sb = new StringBuilder();
        sb.append("=== Log Analysis ===\n");
        sb.append("\n");

        sb.append("Entries by Level:\n");
        for (Map.Entry<String, Integer> entry : levelCount.entrySet()) {
            sb.append("  ").append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
        }
        sb.append("\n");

        // Component with most errors
        String topComponent = "";
        int topCount = 0;
        for (Map.Entry<String, Integer> entry : componentErrors.entrySet()) {
            if (entry.getValue() > topCount) {
                topCount = entry.getValue();
                topComponent = entry.getKey();
            }
        }
        sb.append("Component with Most Errors: ").append(topComponent).append(" (").append(topCount).append(" errors)\n");
        sb.append("\n");

        sb.append("Unique Error Messages:\n");
        for (String msg : uniqueErrorMessages) {
            sb.append("  - ").append(msg).append("\n");
        }
        sb.append("\n");

        // Busiest hour
        String busiestHour = "";
        int busiestCount = 0;
        for (Map.Entry<String, Integer> entry : hourCount.entrySet()) {
            if (entry.getValue() > busiestCount) {
                busiestCount = entry.getValue();
                busiestHour = entry.getKey();
            }
        }
        sb.append("Busiest Hour: ").append(busiestHour).append(":00 (").append(busiestCount).append(" entries)\n");

        System.out.print(sb.toString());
    }
}

