import * as fs from 'fs';

type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };

function isPlainObject(val: JsonValue): val is { [key: string]: JsonValue } {
  return typeof val === "object" && val !== null && !Array.isArray(val);
}

function deepMerge(a: JsonValue, b: JsonValue): JsonValue {
  if (isPlainObject(a) && isPlainObject(b)) {
    const result: { [key: string]: JsonValue } = {};
    const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
    for (const key of keys) {
      if (key in a && key in b) {
        result[key] = deepMerge(a[key], b[key]);
      } else if (key in a) {
        result[key] = a[key];
      } else {
        result[key] = b[key];
      }
    }
    return result;
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    const result: JsonValue[] = [];
    const seen: string[] = [];
    for (const item of [...a, ...b]) {
      const serialized = JSON.stringify(item);
      if (!seen.includes(serialized)) {
        seen.push(serialized);
        result.push(item);
      }
    }
    return result;
  }
  return b;
}

function sortKeys(val: JsonValue): JsonValue {
  if (Array.isArray(val)) {
    return val.map(sortKeys);
  }
  if (isPlainObject(val)) {
    const sorted: { [key: string]: JsonValue } = {};
    const keys = Object.keys(val).sort();
    for (const key of keys) {
      sorted[key] = sortKeys(val[key]);
    }
    return sorted;
  }
  return val;
}

