import Foundation

let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__o428_do/app.log"

guard let content = try? String(contentsOfFile: path, encoding: .utf8) else {
    print("=== Log Analysis ===\n")
    exit(0)
}

let lines = content.components(separatedBy: "\n").filter { !$0.isEmpty }

var levelCounts: [String: Int] = [:]
var errorComponents: [String: Int] = [:]
var uniqueErrorMessages: Set<String> = []
var hourCounts: [String: Int] = [:]

let pattern = "\\[(\\d{4}-\\d{2}-\\d{2}) (\\d{2}):(\\d{2}):(\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.+)"
let regex = try! NSRegularExpression(pattern: pattern)

for line in lines {
    let nsLine = line as NSString
    guard let match = regex.firstMatch(in: line, range: NSRange(location: 0, length: nsLine.length)) else { continue }

    let hour = nsLine.substring(with: match.range(at: 2))
    let level = nsLine.substring(with: match.range(at: 5))
    let component = nsLine.substring(with: match.range(at: 6))
    let message = nsLine.substring(with: match.range(at: 7))

    levelCounts[level, default: 0] += 1
    hourCounts[hour, default: 0] += 1

    if level == "ERROR" {
        errorComponents[component, default: 0] += 1
        uniqueErrorMessages.insert(message)
    }
}

