use std::collections::{HashMap, BTreeMap, HashSet};
use std::fs;

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__o428_do/app.log";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut component_errors: HashMap<String, usize> = HashMap::new();
    let mut unique_error_messages: HashSet<String> = HashSet::new();
    let mut hour_counts: HashMap<String, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let bracket_end = match line.find(']') {
            Some(i) => i,
            None => continue,
        };
        let timestamp = &line[1..bracket_end]; // YYYY-MM-DD HH:MM:SS

        let rest = &line[bracket_end + 1..].trim_start();

        // Find the component in parentheses
        let paren_start = match rest.find('(') {
            Some(i) => i,
            None => continue,
        };
        let paren_end = match rest.find(')') {
            Some(i) => i,
            None => continue,
        };

        let level_str = rest[..paren_start].trim();
        let component = rest[paren_start + 1..paren_end].to_string();

        // Message is after " - "
        let dash_idx = rest.find(" - ");
        let message = match dash_idx {
            Some(i) => rest[i + 3..].to_string(),
            None => String::new(),
        };

        // Count by level
        *level_counts.entry(level_str.to_string()).or_insert(0) += 1;

        // Count errors by component
        if level_str == "ERROR" {
            *component_errors.entry(component.clone()).or_insert(0) += 1;
            unique_error_messages.insert(message.clone());
        }

        // Count by hour
        // timestamp is YYYY-MM-DD HH:MM:SS, hour is at position 11..13
        if timestamp.len() >= 13 {
            let hour = &timestamp[11..13];
            let hour_key = format!("{}:00", hour);
            *hour_counts.entry(hour_key).or_insert(0) += 1;
        }
    }

    // Output
    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    // Component with most errors
    let mut max_component = String::new();
    let mut max_count: usize = 0;
    let mut sorted_components: Vec<(String, usize)> = component_errors.into_iter().collect();
    sorted_components.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    if let Some((ref comp, cnt)) = sorted_components.first() {
        max_component = comp.clone();
        max_count = *cnt;
    }
    println!("Component with Most Errors: {} ({} errors)", max_component, max_count);
    println!();

    // Unique error messages sorted alphabetically
    println!("Unique Error Messages:");
    let mut sorted_messages: Vec<String> = unique_error_messages.into_iter().collect();
    sorted_messages.sort();
    for msg in &sorted_messages {
        println!("  - {}", msg);
    }
    println!();

    // Busiest hour
    let mut sorted_hours: Vec<(String, usize)> = hour_counts.into_iter().collect();
    sorted_hours.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    if let Some((ref hour, cnt)) = sorted_hours.first() {
        println!("Busiest Hour: {} ({} entries)", hour, cnt);
    }
}

