fn format_comma_int(n: i64) -> String {
    let s = n.to_string();
    let mut result = String::new();
    let len = s.len();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

fn format_comma_float(n: f64) -> String {
    let int_part = n.floor() as i64;
    let frac_part = ((n - n.floor()) * 100.0).round() as i64;
    if frac_part >= 100 {
        return format!("{}.00", format_comma_int(int_part + 1));
    }
    format!("{}.{:02}", format_comma_int(int_part), frac_part)
}

