            skipWhitespace();
            pos++; // skip :
            skipWhitespace();
            Object value = parseValue();
            map.put(key, value);
            skipWhitespace();
            if (input.charAt(pos) == ',') { pos++; continue; }
            if (input.charAt(pos) == '}') { pos++; break; }
        }
        return map;
    }

    static List<Object> parseArray() {
        List<Object> list = new ArrayList<>();
        pos++; // skip [
