            list.add(parseValue());
            skipWhitespace();
            if (input.charAt(pos) == ',') { pos++; continue; }
            if (input.charAt(pos) == ']') { pos++; break; }
        }
        return list;
    }

    static String parseString() {
        pos++; // skip opening "
        StringBuilder sb = new StringBuilder();
        while (input.charAt(pos) != '"') {
            if (input.charAt(pos) == '\\') {
                pos++;
                char esc = input.charAt(pos);
                switch (esc) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'u':
                        String hex = input.substring(pos + 1, pos + 5);
                        sb.append((char) Integer.parseInt(hex, 16));
                        pos += 4;
                        break;
                    default: sb.append(esc);
                }
            } else {
                sb.append(input.charAt(pos));
            }
            pos++;
        }
        pos++; // skip closing "
        return sb.toString();
    }

    static Object parseNumber() {
        int start = pos;
        if (input.charAt(pos) == '-') pos++;
        while (pos < input.length() && Character.isDigit(input.charAt(pos))) pos++;
        boolean isDouble = false;
        if (pos < input.length() && input.charAt(pos) == '.') {
            isDouble = true;
            pos++;
            while (pos < input.length() && Character.isDigit(input.charAt(pos))) pos++;
        }
        if (pos < input.length() && (input.charAt(pos) == 'e' || input.charAt(pos) == 'E')) {
            isDouble = true;
            pos++;
            if (pos < input.length() && (input.charAt(pos) == '+' || input.charAt(pos) == '-')) pos++;
            while (pos < input.length() && Character.isDigit(input.charAt(pos))) pos++;
        }
        String numStr = input.substring(start, pos);
        if (isDouble) {
            return Double.parseDouble(numStr);
        } else {
            return Long.parseLong(numStr);
        }
    }

    static Boolean parseBoolean() {
        if (input.startsWith("true", pos)) { pos += 4; return Boolean.TRUE; }
        if (input.startsWith("false", pos)) { pos += 5; return Boolean.FALSE; }
        throw new RuntimeException("Invalid boolean");
    }

    static Object parseNull() {
        if (input.startsWith("null", pos)) { pos += 4; return null; }
        throw new RuntimeException("Invalid null");
    }

    static void skipWhitespace() {
        while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
    }
