static void format_int_comma(long long val, char *buf, int bufsize) {
    int neg = 0;
    if (val < 0) { neg = 1; val = -val; }
    char tmp[64];
    int pos = 0, dc = 0;
    if (val == 0) { tmp[pos++] = '0'; }
    else {
        while (val > 0) {
            if (dc > 0 && dc % 3 == 0) tmp[pos++] = ',';
            tmp[pos++] = '0' + (int)(val % 10);
            val /= 10;
            dc++;
        }
    }
    int off = 0;
    if (neg) buf[off++] = '-';
    for (int i = pos - 1; i >= 0; i--) buf[off++] = tmp[i];
    buf[off] = '\0';
}

static void format_money_int(long long val, char *buf, int bufsize) {
    char tmp[64];
    format_int_comma(val, tmp, sizeof(tmp));
    snprintf(buf, bufsize, "$%s", tmp);
}

static void format_money_dec(double val, char *buf, int bufsize) {
    long long ip = (long long)val;
    int frac = (int)round((val - (double)ip) * 100.0);
    if (frac >= 100) { ip += 1; frac -= 100; }
    char ipbuf[64];
    format_int_comma(ip, ipbuf, sizeof(ipbuf));
    snprintf(buf, bufsize, "$%s.%02d", ipbuf, frac);
}

static int cmp_dept(const void *a, const void *b) {
    const DeptInfo *da = (const DeptInfo *)a;
    const DeptInfo *db = (const DeptInfo *)b;
    return strcmp(da->dept, db->dept);
}

