typedef struct {
    int id;
    char *name;
    double price;
    char *category;
    int stock;
} Product;

static const char *skip_ws(const char *p) {
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    return p;
}

static const char *parse_string_raw(const char *p, char **out) {
    if (*p != '"') return NULL;
    p++;
    const char *start = p;
    while (*p && *p != '"') {
        if (*p == '\\') p++;
        p++;
    }
    size_t len = p - start;
    *out = (char *)malloc(len + 1);
    size_t i = 0;
    const char *q = start;
    while (q < p) {
        if (*q == '\\') {
            q++;
            switch (*q) {
                case '"': (*out)[i++] = '"'; break;
                case '\\': (*out)[i++] = '\\'; break;
                case '/': (*out)[i++] = '/'; break;
                case 'n': (*out)[i++] = '\n'; break;
                case 't': (*out)[i++] = '\t'; break;
                case 'r': (*out)[i++] = '\r'; break;
                case 'b': (*out)[i++] = '\b'; break;
                case 'f': (*out)[i++] = '\f'; break;
                case 'u': {
                    /* basic unicode: just skip 4 hex digits, output '?' */
                    q += 4;
                    (*out)[i++] = '?';
                    break;
                }
                default: (*out)[i++] = *q; break;
            }
        } else {
            (*out)[i++] = *q;
        }
        q++;
    }
    (*out)[i] = '\0';
    if (*p == '"') p++;
    return p;
}

static const char *parse_number(const char *p, double *out) {
    char *end;
    *out = strtod(p, &end);
    return end;
}

static const char *skip_value(const char *p) {
    p = skip_ws(p);
    if (*p == '"') {
        char *tmp;
        p = parse_string_raw(p, &tmp);
        free(tmp);
        return p;
    } else if (*p == '{') {
        p++;
        p = skip_ws(p);
        if (*p == '}') return p + 1;
        while (1) {
            p = skip_ws(p);
            char *tmp;
            p = parse_string_raw(p, &tmp);
            free(tmp);
            p = skip_ws(p);
            if (*p == ':') p++;
            p = skip_value(p);
            p = skip_ws(p);
            if (*p == ',') { p++; continue; }
            if (*p == '}') return p + 1;
            return p;
        }
    } else if (*p == '[') {
        p++;
        p = skip_ws(p);
        if (*p == ']') return p + 1;
        while (1) {
            p = skip_value(p);
            p = skip_ws(p);
            if (*p == ',') { p++; continue; }
            if (*p == ']') return p + 1;
            return p;
        }
    } else if (*p == 't') { p += 4; return p; }
    else if (*p == 'f') { p += 5; return p; }
    else if (*p == 'n') { p += 4; return p; }
    else {
        double d;
        return parse_number(p, &d);
    }
}

