            Some(_) => { while self.pos < self.chars.len() && !matches!(self.chars[self.pos], ',' | '}' | ']') { self.pos += 1; } }
            None => {}
        }
    }

    fn skip_object(&mut self) {
        self.eat('{');
        let mut depth = 1;
        while self.pos < self.chars.len() && depth > 0 {
            match self.chars[self.pos] {
                '{' => depth += 1,
                '}' => depth -= 1,
                '"' => { self.pos += 1; while self.pos < self.chars.len() && self.chars[self.pos] != '"' { if self.chars[self.pos] == '\\' { self.pos += 1; } self.pos += 1; } }
                _ => {}
            }
            self.pos += 1;
        }
    }

    fn skip_array(&mut self) {
        self.eat('[');
        let mut depth = 1;
        while self.pos < self.chars.len() && depth > 0 {
            match self.chars[self.pos] {
                '[' => depth += 1,
                ']' => depth -= 1,
                '"' => { self.pos += 1; while self.pos < self.chars.len() && self.chars[self.pos] != '"' { if self.chars[self.pos] == '\\' { self.pos += 1; } self.pos += 1; } }
                _ => {}
            }
            self.pos += 1;
        }
    }
}

fn dijkstra(adj: &HashMap<String, Vec<(String, usize)>>, nodes: &[String], start: &str) -> HashMap<String, usize> {
    let mut dist: HashMap<String, usize> = HashMap::new();
    for n in nodes {
        dist.insert(n.clone(), usize::MAX);
    }
    dist.insert(start.to_string(), 0);

    let mut heap: BinaryHeap<Reverse<(usize, String)>> = BinaryHeap::new();
    heap.push(Reverse((0, start.to_string())));

    while let Some(Reverse((d, node))) = heap.pop() {
        if d > *dist.get(&node).unwrap_or(&usize::MAX) {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (next, w) in neighbors {
                let nd = d + w;
                if nd < *dist.get(next).unwrap_or(&usize::MAX) {
                    dist.insert(next.clone(), nd);
                    heap.push(Reverse((nd, next.clone())));
                }
            }
        }
    }
    dist
}

