    let content = fs::read_to_string("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__o428_do/graph.json")
        .expect("Failed to read graph.json");

    let mut parser = JsonParser::new(&content);
    parser.eat('{');

    let mut nodes: Vec<String> = Vec::new();
    let mut edges: Vec<(String, String, usize)> = Vec::new();

    loop {
        parser.skip_ws();
        let key = parser.parse_string();
        parser.eat(':');
        parser.skip_ws();
        match key.as_str() {
            "nodes" => nodes = parser.parse_array_of_strings(),
            "edges" => edges = parser.parse_edges(),
            _ => parser.skip_value(),
        }
        parser.skip_ws();
        if parser.peek() == Some(',') {
            parser.pos += 1;
        } else {
            break;
        }
    }
    parser.eat('}');

    let mut adj: HashMap<String, Vec<(String, usize)>> = HashMap::new();
    for n in &nodes {
        adj.entry(n.clone()).or_default();
    }
    for (from, to, w) in &edges {
        adj.entry(from.clone()).or_default().push((to.clone(), *w));
        adj.entry(to.clone()).or_default().push((from.clone(), *w));
    }

    let dist = dijkstra(&adj, &nodes, "A");

    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

    println!("=== Shortest Paths from A ===");
    println!();
    for node in &sorted_nodes {
        let d = dist.get(*node).copied().unwrap_or(usize::MAX);
        println!("A -> {}: {}", node, d);
    }
}
