            if (inStr) {
                if (c == '\\') { i++; continue; }
                if (c == '"') inStr = false;
            } else {
                if (c == '"') inStr = true;
                else if (c == '[' || c == '{') depth++;
                else if (c == ']' || c == '}') { depth--; if (depth == 0) return i; }
            }
        }
        return s.length() - 1;
    }

    private static List<String> splitJsonArray(String content) {
        List<String> items = new ArrayList<>();
        int depth = 0;
        boolean inStr = false;
        int start = 0;
        for (int i = 0; i < content.length(); i++) {
            char c = content.charAt(i);
            if (inStr) {
                if (c == '\\') { i++; continue; }
                if (c == '"') inStr = false;
            } else {
                if (c == '"') inStr = true;
                else if (c == '{' || c == '[') depth++;
                else if (c == '}' || c == ']') depth--;
                else if (c == ',' && depth == 0) {
                    items.add(content.substring(start, i));
                    start = i + 1;
                }
            }
        }
        String last = content.substring(start).trim();
        if (!last.isEmpty()) items.add(last);
        return items;
    }

    private static String extractStringValue(String obj, String key) {
        String search = "\"" + key + "\"";
        int idx = obj.indexOf(search);
        idx = obj.indexOf(':', idx + search.length());
        idx = obj.indexOf('"', idx + 1);
        int end = obj.indexOf('"', idx + 1);
        return obj.substring(idx + 1, end);
    }

    private static int extractIntValue(String obj, String key) {
        String search = "\"" + key + "\"";
        int idx = obj.indexOf(search);
        idx = obj.indexOf(':', idx + search.length());
        idx++;
        while (idx < obj.length() && obj.charAt(idx) == ' ') idx++;
        int end = idx;
        while (end < obj.length() && (Character.isDigit(obj.charAt(end)) || obj.charAt(end) == '-')) end++;
        return Integer.parseInt(obj.substring(idx, end));
    }
}

