#[derive(Debug)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct JsonParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a str) -> Self {
        JsonParser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }

    fn advance(&mut self) -> Option<u8> {
        if self.pos < self.input.len() { let c = self.input[self.pos]; self.pos += 1; Some(c) } else { None }
    }

    fn expect(&mut self, ch: u8) {
        self.skip_ws();
        if self.advance() != Some(ch) {
            panic!("Expected '{}'", ch as char);
        }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.skip_ws();
        match self.peek() {
            Some(b'"') => JsonValue::Str(self.parse_string()),
            Some(b'{') => JsonValue::Object(self.parse_object()),
            Some(b'[') => JsonValue::Array(self.parse_array()),
            Some(b't') => { self.consume_literal("true"); JsonValue::Bool(true) }
            Some(b'f') => { self.consume_literal("false"); JsonValue::Bool(false) }
            Some(b'n') => { self.consume_literal("null"); JsonValue::Null }
            Some(c) if c == b'-' || c.is_ascii_digit() => JsonValue::Number(self.parse_number()),
            _ => panic!("Unexpected character in JSON"),
        }
    }

    fn consume_literal(&mut self, lit: &str) {
        for &b in lit.as_bytes() {
            if self.advance() != Some(b) { panic!("Expected literal '{}'", lit); }
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect(b'"');
        let mut s = String::new();
        loop {
            match self.advance() {
                Some(b'"') => break,
                Some(b'\\') => {
                    match self.advance() {
                        Some(b'"') => s.push('"'),
                        Some(b'\\') => s.push('\\'),
                        Some(b'/') => s.push('/'),
                        Some(b'n') => s.push('\n'),
                        Some(b't') => s.push('\t'),
                        Some(b'r') => s.push('\r'),
                        Some(b'b') => s.push('\u{0008}'),
                        Some(b'f') => s.push('\u{000C}'),
                        Some(b'u') => {
                            let cp = self.parse_hex4();
                            if cp >= 0xD800 && cp <= 0xDBFF {
                                self.expect(b'\\');
                                self.expect(b'u');
                                let lo = self.parse_hex4();
                                let combined = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                s.push(char::from_u32(combined).unwrap_or('\u{FFFD}'));
                            } else {
                                s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                            }
                        }
                        _ => panic!("Invalid escape"),
                    }
                }
                Some(c) => s.push(c as char),
                None => panic!("Unterminated string"),
            }
        }
        s
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut val: u32 = 0;
        for _ in 0..4 {
            let c = self.advance().unwrap();
            let d = match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => panic!("Invalid hex digit"),
            };
            val = val * 16 + d;
        }
        val
    }

    fn parse_number(&mut self) -> f64 {
        let start = self.pos;
        if self.peek() == Some(b'-') { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        s.parse::<f64>().unwrap()
    }

    fn parse_array(&mut self) -> Vec<JsonValue> {
        self.expect(b'[');
        let mut arr = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return arr; }
        loop {
            arr.push(self.parse_value());
            self.skip_ws();
            match self.advance() {
                Some(b']') => break,
                Some(b',') => continue,
                _ => panic!("Expected , or ]"),
            }
        }
        arr
    }

    fn parse_object(&mut self) -> Vec<(String, JsonValue)> {
        self.expect(b'{');
        let mut obj = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return obj; }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            self.expect(b':');
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_ws();
            match self.advance() {
                Some(b'}') => break,
                Some(b',') => continue,
                _ => panic!("Expected , or }}"),
            }
        }
        obj
    }
}

fn get_field<'a>(obj: &'a Vec<(String, JsonValue)>, key: &str) -> Option<&'a JsonValue> {
    obj.iter().find(|(k, _)| k == key).map(|(_, v)| v)
}

fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect");
    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).expect("Failed to send request");

    let mut response = Vec::new();
    stream.read_to_end(&mut response).expect("Failed to read response");
    let response_str = String::from_utf8_lossy(&response);

    let body = if let Some(pos) = response_str.find("\r\n\r\n") {
        &response_str[pos + 4..]
    } else {
        panic!("Invalid HTTP response");
    };

    let mut parser = JsonParser::new(body);
    let json = parser.parse_value();

    let arr = match json {
        JsonValue::Array(a) => a,
        _ => panic!("Expected JSON array"),
    };

    let mut filtered: Vec<(String, f64)> = Vec::new();
    for item in arr {
        if let JsonValue::Object(ref obj) = item {
            let name = match get_field(obj, "name") {
                Some(JsonValue::Str(s)) => s.clone(),
                _ => continue,
            };
            let price = match get_field(obj, "price") {
                Some(JsonValue::Number(n)) => *n,
                _ => continue,
            };
            if price > 50.0 {
                filtered.push((name, price));
            }
        }
    }

    filtered.sort_by(|a, b| a.0.cmp(&b.0));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for (name, price) in &filtered {
        println!("{}: ${:.2}", name, price);
    }
    println!();
    println!("Count: {}", filtered.len());
    let total: f64 = filtered.iter().map(|(_, p)| p).sum();
    println!("Total: ${:.2}", total);
}

