import * as fs from 'fs';
import * as path from 'path';

const rootDir = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__o428_do/project_tree';

interface FileInfo {
  relPath: string;
  lines: number;
  chars: number;
}

function walk(dir: string): FileInfo[] {
  const results: FileInfo[] = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.isSymbolicLink()) continue;
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      const sub = walk(fullPath);
      for (const f of sub) results.push(f);
    } else if (entry.isFile()) {
      const content = fs.readFileSync(fullPath);
      const chars = content.length;
      const text = content.toString('utf-8');
      let lines = 0;
      if (text.length > 0) {
        lines = (text.match(/\n/g) || []).length;
        if (!text.endsWith('\n')) lines++;
      }
      const relPath = path.relative(rootDir, fullPath).split(path.sep).join('/');
      results.push({ relPath, lines, chars });
    }
  }
  return results;
}

const files = walk(rootDir);

const groups: Map<string, FileInfo[]> = new Map();
for (const f of files) {
  const ext = path.extname(f.relPath);
  if (!groups.has(ext)) groups.set(ext, []);
  groups.get(ext)!.push(f);
}

const sortedExts = [...groups.keys()].sort();

const output: string[] = [];
output.push('=== File Tree Analysis ===');
output.push('');

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of sortedExts) {
  const group = groups.get(ext)!;
  group.sort((a, b) => a.relPath.localeCompare(b.relPath));

  const groupLines = group.reduce((s, f) => s + f.lines, 0);
  const groupChars = group.reduce((s, f) => s + f.chars, 0);

  output.push(`Extension: ${ext}`);
  output.push(`  Files: ${group.length}`);
  output.push(`  Total Lines: ${groupLines}`);
  output.push(`  Total Characters: ${groupChars}`);
  for (const f of group) {
    output.push(`    ${f.relPath}: ${f.lines} lines, ${f.chars} chars`);
  }

  totalFiles += group.length;
  totalLines += groupLines;
  totalChars += groupChars;
}

output.push('');
output.push(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);

console.log(output.join('\n'));

