    return parse_value(&p);
}

/* Canonical serialization for comparison (no pretty printing, sorted keys) */
typedef struct {
    char *buf;
    size_t len;
    size_t cap;
} SBuf;

static void sbuf_init(SBuf *s) { s->cap = 256; s->len = 0; s->buf = (char *)malloc(s->cap); s->buf[0] = '\0'; }
static void sbuf_ensure(SBuf *s, size_t extra) {
    if (s->len + extra + 1 > s->cap) {
        while (s->len + extra + 1 > s->cap) s->cap *= 2;
        s->buf = realloc(s->buf, s->cap);
    }
}
static void sbuf_append(SBuf *s, const char *str, size_t n) {
    sbuf_ensure(s, n);
    memcpy(s->buf + s->len, str, n);
    s->len += n;
    s->buf[s->len] = '\0';
}
static void sbuf_append_char(SBuf *s, char c) {
    sbuf_ensure(s, 1);
    s->buf[s->len++] = c;
    s->buf[s->len] = '\0';
}

static void serialize_string_canon(SBuf *s, const char *str) {
    sbuf_append_char(s, '"');
    for (const char *p = str; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': sbuf_append(s, "\\\"", 2); break;
            case '\\': sbuf_append(s, "\\\\", 2); break;
            case '\n': sbuf_append(s, "\\n", 2); break;
            case '\r': sbuf_append(s, "\\r", 2); break;
            case '\t': sbuf_append(s, "\\t", 2); break;
            case '\b': sbuf_append(s, "\\b", 2); break;
            case '\f': sbuf_append(s, "\\f", 2); break;
            default:
                if (c < 0x20) {
                    char tmp[8];
                    snprintf(tmp, sizeof(tmp), "\\u%04x", c);
                    sbuf_append(s, tmp, strlen(tmp));
                } else {
                    sbuf_append_char(s, (char)c);
                }
                break;
        }
    }
    sbuf_append_char(s, '"');
}

static void serialize_canon(SBuf *s, JsonValue *v);

static int cmp_key_canon(const void *a, const void *b) {
    const JsonPair *pa = (const JsonPair *)a;
    const JsonPair *pb = (const JsonPair *)b;
    return strcmp(pa->key, pb->key);
}

static void serialize_canon(SBuf *s, JsonValue *v) {
    switch (v->type) {
        case JSON_NULL: sbuf_append(s, "null", 4); break;
        case JSON_BOOL: sbuf_append(s, v->data.bool_val ? "true" : "false", v->data.bool_val ? 4 : 5); break;
        case JSON_NUMBER: {
            double d = v->data.num_val;
            if (d == (long long)d && fabs(d) < 1e15) {
                char tmp[64];
                snprintf(tmp, sizeof(tmp), "%lld", (long long)d);
                sbuf_append(s, tmp, strlen(tmp));
            } else {
                char tmp[64];
                snprintf(tmp, sizeof(tmp), "%.17g", d);
                sbuf_append(s, tmp, strlen(tmp));
            }
            break;
        }
        case JSON_STRING: serialize_string_canon(s, v->data.str_val); break;
        case JSON_ARRAY: {
            sbuf_append_char(s, '[');
            for (size_t i = 0; i < v->data.array.count; i++) {
                if (i > 0) sbuf_append_char(s, ',');
                serialize_canon(s, v->data.array.items[i]);
            }
            sbuf_append_char(s, ']');
            break;
        }
        case JSON_OBJECT: {
            sbuf_append_char(s, '{');
            /* sort a copy of pairs */
            JsonPair *sorted = (JsonPair *)malloc(sizeof(JsonPair) * v->data.object.count);
            memcpy(sorted, v->data.object.pairs, sizeof(JsonPair) * v->data.object.count);
            qsort(sorted, v->data.object.count, sizeof(JsonPair), cmp_key_canon);
            for (size_t i = 0; i < v->data.object.count; i++) {
                if (i > 0) sbuf_append_char(s, ',');
                serialize_string_canon(s, sorted[i].key);
                sbuf_append_char(s, ':');
                serialize_canon(s, sorted[i].value);
            }
            sbuf_append_char(s, '}');
            free(sorted);
            break;
        }
    }
}

static int json_equal(JsonValue *a, JsonValue *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->data.bool_val == b->data.bool_val;
        case JSON_NUMBER: return a->data.num_val == b->data.num_val;
        case JSON_STRING: return strcmp(a->data.str_val, b->data.str_val) == 0;
        case JSON_ARRAY:
        case JSON_OBJECT: {
            SBuf sa, sb;
            sbuf_init(&sa);
            sbuf_init(&sb);
            serialize_canon(&sa, a);
            serialize_canon(&sb, b);
            int eq = strcmp(sa.buf, sb.buf) == 0;
            free(sa.buf);
            free(sb.buf);
            return eq;
        }
    }
    return 0;
}

static JsonValue *deep_merge(JsonValue *a, JsonValue *b) {
    if (!a) return b;
    if (!b) return a;
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *merged = new_value(JSON_OBJECT);
        merged->data.object.capacity = a->data.object.count + b->data.object.count + 1;
        merged->data.object.pairs = (JsonPair *)malloc(sizeof(JsonPair) * merged->data.object.capacity);
        merged->data.object.count = 0;
        /* Add all from A */
        for (size_t i = 0; i < a->data.object.count; i++) {
            merged->data.object.pairs[merged->data.object.count].key = strdup(a->data.object.pairs[i].key);
            merged->data.object.pairs[merged->data.object.count].value = a->data.object.pairs[i].value;
            merged->data.object.count++;
        }
        /* Merge/add from B */
        for (size_t i = 0; i < b->data.object.count; i++) {
            const char *bkey = b->data.object.pairs[i].key;
            int found = 0;
            for (size_t j = 0; j < merged->data.object.count; j++) {
                if (strcmp(merged->data.object.pairs[j].key, bkey) == 0) {
                    merged->data.object.pairs[j].value = deep_merge(merged->data.object.pairs[j].value, b->data.object.pairs[i].value);
                    found = 1;
                    break;
                }
            }
            if (!found) {
                if (merged->data.object.count >= merged->data.object.capacity) {
                    merged->data.object.capacity *= 2;
                    merged->data.object.pairs = realloc(merged->data.object.pairs, sizeof(JsonPair) * merged->data.object.capacity);
                }
                merged->data.object.pairs[merged->data.object.count].key = strdup(bkey);
                merged->data.object.pairs[merged->data.object.count].value = b->data.object.pairs[i].value;
                merged->data.object.count++;
            }
        }
        return merged;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        /* Concatenate A then B, remove duplicates preserving order */
        size_t total = a->data.array.count + b->data.array.count;
        JsonValue **items = (JsonValue **)malloc(sizeof(JsonValue *) * (total + 1));
        size_t count = 0;
        for (size_t i = 0; i < a->data.array.count; i++) {
            int dup = 0;
            for (size_t j = 0; j < count; j++) {
                if (json_equal(items[j], a->data.array.items[i])) { dup = 1; break; }
            }
            if (!dup) items[count++] = a->data.array.items[i];
        }
        for (size_t i = 0; i < b->data.array.count; i++) {
            int dup = 0;
            for (size_t j = 0; j < count; j++) {
                if (json_equal(items[j], b->data.array.items[i])) { dup = 1; break; }
            }
            if (!dup) items[count++] = b->data.array.items[i];
        }
        JsonValue *arr = new_value(JSON_ARRAY);
        arr->data.array.items = items;
        arr->data.array.count = count;
        arr->data.array.capacity = total;
        return arr;
    }
    /* Scalar conflict: B overrides A */
    return b;
}

/* Pretty-print output */
static void print_indent(int depth) {
    for (int i = 0; i < depth; i++) printf("  ");
}

static void print_string_pretty(const char *str) {
    putchar('"');
    for (const char *p = str; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': printf("\\\""); break;
            case '\\': printf("\\\\"); break;
            case '\n': printf("\\n"); break;
            case '\r': printf("\\r"); break;
            case '\t': printf("\\t"); break;
            case '\b': printf("\\b"); break;
            case '\f': printf("\\f"); break;
            default:
                if (c < 0x20) printf("\\u%04x", c);
                else putchar(c);
                break;
        }
    }
    putchar('"');
}

static int cmp_key_pretty(const void *a, const void *b) {
    const JsonPair *pa = (const JsonPair *)a;
    const JsonPair *pb = (const JsonPair *)b;
    return strcmp(pa->key, pb->key);
}

static void print_json(JsonValue *v, int depth) {
    switch (v->type) {
        case JSON_NULL: printf("null"); break;
        case JSON_BOOL: printf("%s", v->data.bool_val ? "true" : "false"); break;
        case JSON_NUMBER: {
            double d = v->data.num_val;
            if (d == (long long)d && fabs(d) < 1e15) {
                printf("%lld", (long long)d);
            } else {
                printf("%.17g", d);
            }
            break;
        }
        case JSON_STRING: print_string_pretty(v->data.str_val); break;
        case JSON_ARRAY: {
            if (v->data.array.count == 0) { printf("[]"); break; }
            printf("[\n");
            for (size_t i = 0; i < v->data.array.count; i++) {
                print_indent(depth + 1);
                print_json(v->data.array.items[i], depth + 1);
                if (i + 1 < v->data.array.count) printf(",");
                printf("\n");
            }
            print_indent(depth);
            printf("]");
            break;
        }
        case JSON_OBJECT: {
            if (v->data.object.count == 0) { printf("{}"); break; }
            printf("{\n");
            JsonPair *sorted = (JsonPair *)malloc(sizeof(JsonPair) * v->data.object.count);
            memcpy(sorted, v->data.object.pairs, sizeof(JsonPair) * v->data.object.count);
            qsort(sorted, v->data.object.count, sizeof(JsonPair), cmp_key_pretty);
            for (size_t i = 0; i < v->data.object.count; i++) {
                print_indent(depth + 1);
                print_string_pretty(sorted[i].key);
                printf(": ");
                print_json(sorted[i].value, depth + 1);
                if (i + 1 < v->data.object.count) printf(",");
                printf("\n");
            }
            free(sorted);
            print_indent(depth);
            printf("}");
            break;
        }
    }
}

int main(void) {
    const char *path_a = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__o428_do/config_a.json";
    const char *path_b = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__o428_do/config_b.json";

    char *text_a = read_file(path_a);
    char *text_b = read_file(path_b);

    JsonValue *a = parse_json(text_a);
    JsonValue *b = parse_json(text_b);

    JsonValue *merged = deep_merge(a, b);

    print_json(merged, 0);
    printf("\n");

    free(text_a);
    free(text_b);
    return 0;
