var files: [(relativePath: String, ext: String, lines: Int, chars: Int)] = []

func isSymlink(_ path: String) -> Bool {
    var st = stat()
    if lstat(path, &st) == 0 {
        return (st.st_mode & S_IFMT) == S_IFLNK
    }
    return false
}

func isDirectoryPath(_ path: String) -> Bool {
    var st = stat()
    if lstat(path, &st) == 0 {
        return (st.st_mode & S_IFMT) == S_IFDIR
    }
    return false
}

func walkDirectory(_ path: String) {
    let fm = FileManager.default
    guard let contents = try? fm.contentsOfDirectory(atPath: path) else { return }
    for name in contents {
        let fullPath = path + "/" + name
        if isSymlink(fullPath) { continue }
        if isDirectoryPath(fullPath) {
            walkDirectory(fullPath)
        } else {
            let relativePath = String(fullPath.dropFirst(basePath.count + 1))
            let ext = (name as NSString).pathExtension
