#define INF 1e18

typedef struct {
    char *name;
    int idx;
} Node;

typedef struct {
    int to;
    double weight;
} AdjEntry;

typedef struct {
    AdjEntry *entries;
    int count;
    int cap;
} AdjList;

typedef struct {
    double dist;
    int node;
} HeapItem;

typedef struct {
    HeapItem *items;
    int size;
    int cap;
} MinHeap;

static void heap_push(MinHeap *h, double dist, int node) {
    if (h->size >= h->cap) {
        h->cap *= 2;
        h->items = realloc(h->items, h->cap * sizeof(HeapItem));
    }
    int i = h->size++;
    h->items[i].dist = dist;
    h->items[i].node = node;
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (h->items[parent].dist <= h->items[i].dist) break;
        HeapItem tmp = h->items[parent];
        h->items[parent] = h->items[i];
        h->items[i] = tmp;
        i = parent;
    }
}

static HeapItem heap_pop(MinHeap *h) {
    HeapItem top = h->items[0];
    h->items[0] = h->items[h->size - 1];
