        int[][] A = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        int[][] B = {{9, 8, 7}, {6, 5, 4}, {3, 2, 1}};

        int[][] C = multiply(A, B);
        long det = determinant(C);

        System.out.println("=== Matrix Operations ===");
        System.out.println();
        System.out.println("Matrix A:");
        printMatrix(A);
        System.out.println();
        System.out.println("Matrix B:");
        printMatrix(B);
        System.out.println();
        System.out.println("A x B =");
        printMatrix(C);
        System.out.println();
        System.out.println("Determinant: " + det);
    }

    static int[][] multiply(int[][] A, int[][] B) {
        int n = A.length;
        int[][] C = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int sum = 0;
                for (int k = 0; k < n; k++) {
                    sum += A[i][k] * B[k][j];
                }
                C[i][j] = sum;
            }
        }
        return C;
    }

    static long determinant(int[][] M) {
        int n = M.length;
        if (n == 1) return M[0][0];
        if (n == 2) return (long) M[0][0] * M[1][1] - (long) M[0][1] * M[1][0];
        long det = 0;
        for (int j = 0; j < n; j++) {
            long sign = (j % 2 == 0) ? 1 : -1;
            det += sign * M[0][j] * determinant(minor(M, 0, j));
        }
        return det;
    }

    static int[][] minor(int[][] M, int row, int col) {
        int n = M.length;
        int[][] sub = new int[n - 1][n - 1];
        int si = 0;
        for (int i = 0; i < n; i++) {
            if (i == row) continue;
            int sj = 0;
            for (int j = 0; j < n; j++) {
                if (j == col) continue;
                sub[si][sj] = M[i][j];
                sj++;
            }
            si++;
        }
        return sub;
    }

    static void printMatrix(int[][] M) {
        for (int[] row : M) {
            StringBuilder sb = new StringBuilder("  ");
            for (int j = 0; j < row.length; j++) {
                if (j > 0) sb.append(" ");
                sb.append(String.format("%4d", row[j]));
            }
            System.out.println(sb.toString());
        }
    }
}
